import { Injectable } from '@angular/core';
import { ReadingMouseData } from '../models/ReadingMouseData';
import { HttpClient } from '@angular/common/http';

@Injectable({
  providedIn: 'root'
})
export class ReadingMouseDataService {

  private apiUrl = 'http://localhost:4000/reading';

  private data: ReadingMouseData[] = [];
  private tracking = false;
  private case = '';

  constructor(private http: HttpClient) { }

  private track = (e: MouseEvent) => {
    const x = e.clientX;
    const y = e.clientY;

    this.data.push({
      x,
      y,
      stamp: Date.now()
    });

  };

  startTracking(t: string) {
    if (!this.tracking) {
      document.addEventListener('mousemove', this.track);
      this.tracking = true;
      this.case = t;
    }
  }

  stopTracking() {
    if (this.tracking) {
      document.removeEventListener('mousemove', this.track);
      this.tracking = false;
      const movements = [...this.data]; // kopija da ne gubimo referencu
      const sessionId = localStorage.getItem('sessionId');

      if (!sessionId) {
        console.error('[MouseTracker] Nema sessionId u localStorage!');
        return;
      }


      this.sendMouseData(this.case, movements, sessionId).subscribe({
        next: () => console.log(`[MouseTracker] Podaci poslati za test: ${this.case}`),
        error: (err) => console.error('[MouseTracker] Greška pri slanju:', err)
      });

      this.case = '';
    }
  }

  getData(): ReadingMouseData[] {
    return this.data;
  }

  clear() {
    this.data = [];
    this.tracking = false;
  }

  sendMouseData(testName: string, events: ReadingMouseData[], sessionId: string) {
    let data = {
      test: testName, mousedata: events
    }
    return this.http.post<string>(`${this.apiUrl}/sendData`, data)

  }
}
